    "ve": "A hu sumbedzwi tshivhalo tsha dzikhilogiramu ngauri {places} hu na zwipiḓa zwa u ṱavha zwi dzhianelaho kana zwi songo teaho. Lugisani nzudzanyo phanḓa ha u shumisa tshikalo."
