    "st": "Ha ho papiso ya dikilogerama e fumanehang hobane ha ho sejalo sa dijo moralong ona se nang le tekanyo ya kg/m² e netefaditsweng. Tekanyo e sa fumaneheng ha se kotulo ya 0kg.",
