    "st": "Buisana ka mefuta e bitswang ka mabitso ditekong tsa Afrika Borwa le mofani wa peo kapa moeletsi wa temo wa sebaka. Boteng ba ho reka hona jwale le ho lokela ha sebaka sena ha di a netefatswa; o se ke wa kenya mofuta o mong sebakeng sa wona ka sephiri.",
    "ts": "Burisana hi tinxaka leti nga ni mavito ta mindzingo ya Afrika Dzonga ni muphakeri wa mbewu kumbe mutsundzuxi wa vurimi wa ndhawu. Ku kumeka ka tona ku xaviwa sweswi ni ku faneleka ka tona eka ndhawu leyi a swi tiyisisiwanga; u nga sivi muxaka hi wun’wana u nga tivisanga.",
    "ve": "Haseledzani tshaka dzi re na madzina dza milingo ya Afrika Tshipembe na muṋetshedzi wa mbeu kana mueletshedzi wa vhulimi wa henefho. U wanala ha u renga ha zwino na u tea ha fhethu hafha a zwo ngo khwaṱhisedzwa; ni songo tshintsha lushaka nga luṅwe ni sa zwi buli.",
