    "english": "Malekutu, Mpumalanga, 1998/99; rainfed mid-December sowing, sandy loam, no fertiliser. Paired days after planting / grain kg/ha: ICPL 88039 127 / 1823; ICPL 85010 129 / 1525; ICPL 87091 140 / 1299; ICPL 87051 193 / 978; ICEAP 00053 231 / 918. Grain differences within each trial were not significant. Visually checked Tables 1–2 (PDF pp43–44). These are dry-grain observations, not green-seed picking dates or nationwide yield defaults.",
    "zu": "Malekutu, Mpumalanga, 1998/99; ukutshala maphakathi noDisemba kuncike emvuleni, emhlabathini we-sandy loam, kungekho manyolo. Izinsuku ngemva kokutshala / izinhlamvu kg/ha zibhangqwe kanje: ICPL 88039 127 / 1823; ICPL 85010 129 / 1525; ICPL 87091 140 / 1299; ICPL 87051 193 / 978; ICEAP 00053 231 / 918. Umehluko wezinhlamvu ocwaningweni ngalunye awubalulekile ngokwezibalo. Amathebula 1–2 ahlolwe ngokuwabuka (PDF pp43–44). Lokhu okubonwe ngezinhlamvu ezomile, akuzona izinsuku zokuvuna imbewu eluhlaza noma izivuno ezimisiwe zezwe lonke.",
    "st": "Malekutu, Mpumalanga, 1998/99; ho jala bohareng ba Tshitwe ho itshetlehileng ka pula, mobung wa sandy loam, ho se na manyolo. Matsatsi ka mora ho jala / dijo-thollo kg/ha di tsamaisana tjena: ICPL 88039 127 / 1823; ICPL 85010 129 / 1525; ICPL 87091 140 / 1299; ICPL 87051 193 / 978; ICEAP 00053 231 / 918. Diphapang tsa dijo-thollo tekong ka nngwe ha di bohlokwa ka dipalopalo. Ho hlahlobilwe Dithebole 1–2 ka ho di sheba (PDF pp43–44). Tsena ke tse bonweng ka dijo-thollo tse ommeng, eseng matsatsi a ho kotula peo e tala kapa chai e behilweng bakeng sa naha yohle.",
    "ts": "Malekutu, Mpumalanga, 1998/99; ku byala exikarhini ka N'wendzamhala ku titshege hi mpfula, eka misava ya sandy loam, ku nga ri na manyoro. Masiku endzhaku ko byala / ndzoho kg/ha swi fambisana hi ndlela leyi: ICPL 88039 127 / 1823; ICPL 85010 129 / 1525; ICPL 87091 140 / 1299; ICPL 87051 193 / 978; ICEAP 00053 231 / 918. Ku hambana ka ndzoho endzeni ka ndzingo wun’wana ni wun’wana a ku nga ri na nkoka hi tinhlayo ta ndzavisiso. Matafula ya 1–2 ma kamberiwile hi ku ma languta (PDF pp43–44). Leyi i mivono ya ndzoho leyi omeke, ku nga ri masiku yo tshovela mbewu ya rihlaza kumbe mintshovelo leyi vekiweke ya tiko hinkwaro.",
    "ve": "Malekutu, Mpumalanga, 1998/99; u ṱavha vhukati ha Nyendavhusiku ho ḓitikaho nga mvula, kha mavu a sandy loam, hu si na manyoro. Maḓuvha nga murahu ha u ṱavha / thoro kg/ha zwi yelana nga heyi nḓila: ICPL 88039 127 / 1823; ICPL 85010 129 / 1525; ICPL 87091 140 / 1299; ICPL 87051 193 / 978; ICEAP 00053 231 / 918. Phambano dza thoro kha mulingo muṅwe na muṅwe a dzi dza ndeme nga mbalo dza ṱhoḓisiso. Thebuḽu 1–2 dzo ṱolwa nga u dzi sedza (PDF pp43–44). Izwi ndi zwe zwa vhonwa nga thoro dzo omaho, hu si maḓuvha a u kaṋa mbeu dala kana khaṋo dzo tiwaho dza shango ḽoṱhe.",
