    "zu": "Ukuhlelwa kwezilimo zokuthengisa kuqhathanisa kuphela izilinganiso eziphansi ezicatshangelwayo zesisindo esisha nge-kg/m² ngomjikelezo ngamunye wesilimo. Akulinganisi inzuzo, umsoco, isidingo sabathengi noma isivuno sonyaka esiphezulu kunazo zonke; sebenzisa ulwazi lwakho ngabathengi namanani ngaphambi kokubekela izilimo indawo.",
