    "st": "Ha ho moralo wa dijalo o iketsang o entsweng hobane nosetso e tshepahalang e ne e sa netefatswa, mme pula le motjheso tsa kgwedi ka nngwe tsa sebaka sena di ne di sa fumanehe ho rera sehla se itshetlehileng ka pula. Mokgwa ona o kopanya ka boomo dipotoloho tse latellanang tsa dijalo, mme lebitso la pula ya lebatowa ha le pake hore polasi ena e ka di nosetsa.",
