    "ve": "A hu na pulane ya zwimela yo ḓiitelaho yo bveledzwaho ngauri u sheledza ho fhulufhedzeaho a ho ngo khwaṱhisedzwa, nahone mvula na mufhiso zwa ṅwedzi muṅwe na muṅwe zwa henefha a zwo ngo wanala u pulana khalaṅwaha yo ḓisendekaho nga mvula. Maitele aya a dzhenisa nga khole mitevhe ya zwimela i tevhelanaho, nahone dzina ḽa mvula ya dzingu a ḽi khwaṱhisedzi uri bulasi iyi i nga zwi sheledza.",
    "generatedScope": "plan-note"
