    "ve": "Zwe zwa fuwiwa zwi tea u ṋewa maḓi na zwiḽiwa nga u ṱavhanya musi zwi tshi swika gammbeni ya vhusiku kana fhethu ha magumo hune zwa khou ya hone.",
