    "st": "Dinku tse lemetseng, tse holofetseng kapa tse foufetseng di tshwanetse ho etellwa pele ha ho hlajwa, kapa ho hlajwa ka tshohanyetso, ho thibela bohloko kapa mahlomola a eketsehileng.",
