    "st": "Mesebetsi ya ho rua dinotshi le ditshebeletso tsa morui wa dinotshi ya hirwang di hloka setifikeiti sa ngodiso se sebetsang. Hlahloba setifikeiti pele o sebedisa morui wa dinotshi.",
