    "ts": "Xisaka xin'wana ni xin'wana xa tinyoxi xi fanele ku funghiwa hi nomboro ya ntsariso ya mufuwi wa tinyoxi hi ndlela leyi vonakaka kahle ni ku hlayeka.",
