    "ve": "U ṱhavhela zwiḽiwa zwa muṱa wa mulimi nga woṱhe, kana ndivho dza mvelele kana vhurereli, a zwi vhofhiwi nga mulayo wa fhethu ha u ṱhavhela zwifuwo."
